import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Has an invalid schema',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_tool/);
  });

  it('rejects input missing a required property with a ToolResponse naming the property and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsLocationAndRequired: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsLocationAndRequired: true,
    });
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged once', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return '20C';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin', extraKey: 42});

    expect({response, receivedInputs}).toEqual({
      response: {result: '20C'},
      receivedInputs: [{location: 'Berlin', extraKey: 42}],
    });
  });

  it('rejects a wrong-typed property naming the field path and expected type without leaking the value in the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_customer',
        description: 'Look up customer by secret token',
        inputSchema: {
          type: 'object',
          properties: {secretToken: {type: 'string'}},
          required: ['secretToken'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('lookup_customer', {secretToken: 987654321});

    expect({
      executorCalls,
      mentionsField: response.result.includes('secretToken'),
      mentionsType: response.result.includes('string'),
      leaksInResult: response.result.includes('987654321'),
      leaksInLogs: recordedLogs.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsType: true,
      leaksInResult: false,
      leaksInLogs: false,
    });
  });

  it('throws Unknown tool: <name> when executing an unregistered tool', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('compiles a static tool schema once at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition = {
      name: 'get_weather',
      description: 'Get weather',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async () => 'sunny');
    for (let i = 0; i < 10; i += 1) {
      await registry.execute('get_weather', {location: 'Berlin'});
    }

    expect(schemaReads).toBe(1);
  });

  it('validates a function-valued tool definition against the schema returned on each call while caching by schema reference', async () => {
    const registry = new ToolRegistry();
    const schemaRequiringCity: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const schemaRequiringZip: Record<string, unknown> = {
      type: 'object',
      properties: {zip: {type: 'number'}},
      required: ['zip'],
    };
    let currentSchema = schemaRequiringCity;
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Look up by active schema',
        inputSchema: currentSchema,
      }),
      async input => JSON.stringify(input)
    );

    const firstValid = await registry.execute('dynamic_lookup', {city: 'Paris'});
    currentSchema = schemaRequiringZip;
    const staleInputRejected = await registry.execute('dynamic_lookup', {city: 'Paris'});
    const secondValid = await registry.execute('dynamic_lookup', {zip: 75001});

    expect({
      firstValid: firstValid.result,
      rejectedMentionsZip: staleInputRejected.result.includes('zip') && /required/i.test(staleInputRejected.result),
      secondValid: secondValid.result,
    }).toEqual({
      firstValid: '{"city":"Paris"}',
      rejectedMentionsZip: true,
      secondValid: '{"zip":75001}',
    });
  });
});

import AjvPackage, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

const Ajv = AjvPackage.default;
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicSchemaCache = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private getValidator(name: string, tool: StoredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const {inputSchema} = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicSchemaCache.get(inputSchema);
    if (cached) return cached;
    const compiled = compileSchema(name, inputSchema);
    this.dynamicSchemaCache.set(inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate =
      typeof definition === 'function' ? undefined : compileSchema(resolved.name, definition.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  // Rejects schema-invalid input as a ToolResponse and throws only on an unknown tool name (specs/hal-engine-tool-input-validation/spec.md).
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.getValidator(name, tool);
    if (!validate(input)) {
      const failures = (validate.errors ?? []).map(formatValidationError);
      log.warn('tool', 'input validation failed', {name, failures});
      return {result: `Invalid input for tool "${name}": ${failures.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${name}": ${reason}`, {cause: error});
  }
}

function formatValidationError(error: ErrorObject): string {
  const path = error.instancePath || '<root>';
  const message = error.message ?? `failed ${error.keyword}`;
  return `${path} ${message}`;
}

